CREATE TYPE public.promise_status AS ENUM ('ainda não avaliável','em andamento','cumprida','parcialmente cumprida','não cumprida');
CREATE TYPE public.source_provenance AS ENUM ('official','non_official','unknown');
CREATE TYPE public.verification_state AS ENUM ('pending','approved','rejected');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role='reviewer'),UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY; CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_promise_reviewer() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='reviewer') $$;
CREATE TABLE public.politicians(id text PRIMARY KEY,name text NOT NULL);
GRANT SELECT ON public.politicians TO anon,authenticated; GRANT ALL ON public.politicians TO service_role;
ALTER TABLE public.politicians ENABLE ROW LEVEL SECURITY; CREATE POLICY public_politicians ON public.politicians FOR SELECT USING(true);
CREATE TABLE public.political_promises(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),politician_id text NOT NULL REFERENCES public.politicians(id),legacy_key text UNIQUE,title text NOT NULL CHECK(length(title) BETWEEN 1 AND 500),description text NOT NULL DEFAULT '' CHECK(length(description)<=10000),category text NOT NULL DEFAULT 'Outros',promised_on date,deadline date,published boolean NOT NULL DEFAULT false,legacy_assertion jsonb,date_uncertainty text,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),CHECK(deadline IS NULL OR promised_on IS NULL OR deadline>promised_on));
GRANT SELECT ON public.political_promises TO anon,authenticated; GRANT ALL ON public.political_promises TO service_role;
ALTER TABLE public.political_promises ENABLE ROW LEVEL SECURITY; CREATE POLICY visible_promises ON public.political_promises FOR SELECT USING(published OR created_by=auth.uid() OR public.is_promise_reviewer());
CREATE TABLE public.promise_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),promise_id uuid NOT NULL REFERENCES public.political_promises(id),url text NOT NULL CHECK(url ~ '^https?://' AND length(url)<=4000),publisher text,provenance public.source_provenance NOT NULL DEFAULT 'unknown',quotation text,published_on date,accessed_on date,timestamp_start integer CHECK(timestamp_start>=0),timestamp_end integer,uncertainty text,published boolean NOT NULL DEFAULT false,CHECK(timestamp_end IS NULL OR timestamp_start IS NOT NULL AND timestamp_end>=timestamp_start));
GRANT SELECT ON public.promise_sources TO anon,authenticated; GRANT ALL ON public.promise_sources TO service_role;
ALTER TABLE public.promise_sources ENABLE ROW LEVEL SECURITY; CREATE POLICY visible_sources ON public.promise_sources FOR SELECT USING((published AND EXISTS(SELECT 1 FROM public.political_promises p WHERE p.id=promise_id AND p.published)) OR public.is_promise_reviewer());
CREATE TABLE public.promise_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),promise_id uuid NOT NULL REFERENCES public.political_promises(id),submitted_by uuid NOT NULL,submitted_at timestamptz NOT NULL DEFAULT now(),description text NOT NULL CHECK(length(description) BETWEEN 1 AND 10000),url text NOT NULL CHECK(url ~ '^https?://' AND length(url)<=4000),publisher text,provenance public.source_provenance NOT NULL DEFAULT 'unknown',quotation text CHECK(length(quotation)<=10000),published_on date,accessed_on date,timestamp_start integer CHECK(timestamp_start>=0),timestamp_end integer,CHECK(timestamp_end IS NULL OR timestamp_start IS NOT NULL AND timestamp_end>=timestamp_start));
GRANT SELECT ON public.promise_evidence TO anon,authenticated; GRANT ALL ON public.promise_evidence TO service_role;
ALTER TABLE public.promise_evidence ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.evidence_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),evidence_id uuid NOT NULL REFERENCES public.promise_evidence(id),decision public.verification_state NOT NULL CHECK(decision<>'pending'),reviewer_id uuid NOT NULL,reviewed_at timestamptz NOT NULL DEFAULT now(),rationale text NOT NULL CHECK(length(rationale) BETWEEN 1 AND 10000));
GRANT SELECT ON public.evidence_reviews TO anon,authenticated; GRANT ALL ON public.evidence_reviews TO service_role;
ALTER TABLE public.evidence_reviews ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.evidence_is_public(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE((SELECT r.decision='approved' AND p.published FROM public.promise_evidence e JOIN public.political_promises p ON p.id=e.promise_id JOIN public.evidence_reviews r ON r.evidence_id=e.id WHERE e.id=_id ORDER BY r.reviewed_at DESC,r.id DESC LIMIT 1),false) $$;
CREATE POLICY visible_evidence ON public.promise_evidence FOR SELECT USING(public.evidence_is_public(id) OR submitted_by=auth.uid() OR public.is_promise_reviewer());
CREATE POLICY visible_evidence_reviews ON public.evidence_reviews FOR SELECT USING(public.evidence_is_public(evidence_id) OR public.is_promise_reviewer() OR EXISTS(SELECT 1 FROM public.promise_evidence e WHERE e.id=evidence_id AND e.submitted_by=auth.uid()));
CREATE TABLE public.promise_assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),promise_id uuid NOT NULL REFERENCES public.political_promises(id),version integer NOT NULL CHECK(version>0),status public.promise_status NOT NULL,fulfillment_percent numeric CHECK(fulfillment_percent BETWEEN 0 AND 100),criteria text NOT NULL CHECK(length(criteria) BETWEEN 1 AND 10000),methodology text NOT NULL CHECK(length(methodology) BETWEEN 1 AND 10000),rationale text NOT NULL CHECK(length(rationale) BETWEEN 1 AND 10000),evidence_ids uuid[] NOT NULL DEFAULT '{}',verification public.verification_state NOT NULL DEFAULT 'pending',submitted_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),reviewer_id uuid,reviewed_at timestamptz,supersedes uuid REFERENCES public.promise_assessments(id),UNIQUE(promise_id,version),CHECK((verification='pending' AND reviewer_id IS NULL AND reviewed_at IS NULL) OR (verification<>'pending' AND reviewer_id IS NOT NULL AND reviewed_at IS NOT NULL)),CHECK(fulfillment_percent IS NULL OR cardinality(evidence_ids)>0));
GRANT SELECT ON public.promise_assessments TO anon,authenticated; GRANT ALL ON public.promise_assessments TO service_role;
ALTER TABLE public.promise_assessments ENABLE ROW LEVEL SECURITY; CREATE POLICY visible_assessments ON public.promise_assessments FOR SELECT USING((verification='approved' AND EXISTS(SELECT 1 FROM public.political_promises p WHERE p.id=promise_id AND p.published)) OR submitted_by=auth.uid() OR public.is_promise_reviewer());
CREATE FUNCTION public.prevent_audit_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Audit records are immutable; append a new version'; END $$;
CREATE TRIGGER immutable_assessments BEFORE UPDATE OR DELETE ON public.promise_assessments FOR EACH ROW EXECUTE FUNCTION public.prevent_audit_mutation();
CREATE TRIGGER immutable_evidence BEFORE UPDATE OR DELETE ON public.promise_evidence FOR EACH ROW EXECUTE FUNCTION public.prevent_audit_mutation();
CREATE TRIGGER immutable_reviews BEFORE UPDATE OR DELETE ON public.evidence_reviews FOR EACH ROW EXECUTE FUNCTION public.prevent_audit_mutation();
CREATE INDEX promises_politician ON public.political_promises(politician_id); CREATE INDEX assessments_latest ON public.promise_assessments(promise_id,version DESC); CREATE INDEX evidence_promise ON public.promise_evidence(promise_id); CREATE INDEX evidence_review_latest ON public.evidence_reviews(evidence_id,reviewed_at DESC);